import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"模型层 core","description":"","frontmatter":{},"headers":[],"relativePath":"reference/core.md","filePath":"reference/core.md","lastUpdated":1792431968000}`),a={name:`reference/core.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="模型层-core" tabindex="-1">模型层 core <a class="header-anchor" href="#模型层-core" aria-label="Permalink to “模型层 core”">​</a></h1><p><code>@xihan-report/core</code> 是纯 TypeScript 的模型层：报表定义的类型、校验、取数请求、计算、编辑操作与扩展的合并，不依赖 DOM，浏览器、Node.js 与其它 JavaScript 运行环境里都能用。报表定义的字段见<a href="./schema">报表定义类型</a>，属性见<a href="./properties">属性</a>。下表按源码模块列出全部导出。</p><h2 id="全部导出" tabindex="-1">全部导出 <a class="header-anchor" href="#全部导出" aria-label="Permalink to “全部导出”">​</a></h2><h3 id="binding-plans" tabindex="-1">binding-plans <a class="header-anchor" href="#binding-plans" aria-label="Permalink to “binding-plans”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>FillBindingsOptions</code></td><td>接口</td><td>补全绑定的选项。</td></tr><tr><td><code>planFillBindings</code></td><td>函数</td><td>补全一张卡片的必填绑定：取数形状为 query 的卡片交给它种类的 fillBindings，拿到查询里现有的维度与度量 id。</td></tr></tbody></table><h3 id="card-data" tabindex="-1">card-data <a class="header-anchor" href="#card-data" aria-label="Permalink to “card-data”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>bodyQuery</code></td><td>函数</td><td>扩展视图作主体时的查询：取数形状为 query 的扩展视图；别的主体为 undefined。</td></tr><tr><td><code>cardDataset</code></td><td>函数</td><td>卡片取数的数据集 id；不取数的卡片为 undefined。</td></tr><tr><td><code>cardQuery</code></td><td>函数</td><td>卡片的查询：图表与指标卡片，或取数形状为 query 的扩展卡片；别的卡片为 undefined。</td></tr><tr><td><code>cardView</code></td><td>函数</td><td>卡片带的视图：表格卡片，或取数形状为 view 的扩展卡片；别的卡片为 undefined。</td></tr><tr><td><code>isDataView</code></td><td>函数</td><td>主体是不是明细表、分组报表或交叉表。</td></tr><tr><td><code>QueryBinding</code></td><td>接口</td><td>带查询的取数部分：数据集、参数绑定与聚合查询。</td></tr></tbody></table><h3 id="card-templates" tabindex="-1">card-templates <a class="header-anchor" href="#card-templates" aria-label="Permalink to “card-templates”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>cardTemplate</code></td><td>函数</td><td>新卡片的模板：取数用 dataset，查询、图表与视图里的字段绑定都留空（空字符串或空列表），由设计器随后填上。</td></tr><tr><td><code>CardTemplate</code></td><td>类型</td><td>内置种类的新卡片模板。</td></tr><tr><td><code>cardTypeOf</code></td><td>函数</td><td>卡片的种类：内置的按图表或视图类型细分，扩展卡片就是它的种类名。</td></tr><tr><td><code>REPORT_CARD_TYPES</code></td><td>常量</td><td>全部卡片种类：图表、指标、表格依次排列。</td></tr><tr><td><code>ReportCardType</code></td><td>类型</td><td>卡片种类：chart.&lt;图表类型&gt;、metric、table.&lt;视图类型&gt;。</td></tr></tbody></table><h3 id="data-plans" tabindex="-1">data-plans <a class="header-anchor" href="#data-plans" aria-label="Permalink to “data-plans”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>DataCascade</code></td><td>接口</td><td>删除时一并删掉的别处：列表项、筛选条件、明细排序、联动目标（目标删空时连同联动）与参数绑定。</td></tr><tr><td><code>DataRemoval</code></td><td>接口</td><td>删除计划：操作合为一步撤销，cascade 是一并删掉的别处的数目。</td></tr><tr><td><code>datasetUsage</code></td><td>函数</td><td>使用这个数据集的卡片与视图的数目。</td></tr><tr><td><code>planRemoveDataset</code></td><td>函数</td><td>删除数据集；还有卡片或视图使用它时抛 RangeError，数据集不存在时也抛 RangeError。</td></tr><tr><td><code>planRemoveField</code></td><td>函数</td><td>删除字段：取这个字段的列表项走 planRemoveItem 一并删掉（连带它们的引用），绑定这个数据集的对象里以它为字段的筛选条件、明细排序与联动目标也删掉（目标删空的联动整条删掉），最后 removeField。</td></tr><tr><td><code>planRemoveParameter</code></td><td>函数</td><td>删除报表参数：以它为操作数的筛选条件与引用它的参数绑定一并删掉，最后 removeParameter。</td></tr><tr><td><code>planRenameParameter</code></td><td>函数</td><td>报表参数改名：updateParameter，并把引用它的地方一起改掉——筛选条件的操作数、参数绑定，以及计算字段、公式度量与列汇总公式里的 $名字。</td></tr></tbody></table><h3 id="engine-aggregate" tabindex="-1">engine/aggregate <a class="header-anchor" href="#engine-aggregate" aria-label="Permalink to “engine/aggregate”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>createRollupAccumulator</code></td><td>函数</td><td>已聚合值的再汇总累加器：sum 与 count 相加，min / max 取最值，规则同 createAccumulator。</td></tr><tr><td><code>isAdditive</code></td><td>函数</td><td>聚合方式能否由已聚合值再汇总得到。</td></tr><tr><td><code>NEEDS_ROLLUP</code></td><td>常量</td><td>已聚合值无法再汇总、需要使用方另给汇总值的标记。</td></tr></tbody></table><h3 id="engine-chart-data" tabindex="-1">engine/chart-data <a class="header-anchor" href="#engine-chart-data" aria-label="Permalink to “engine/chart-data”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>CartesianChartData</code></td><td>接口</td><td>直角坐标图的数据：rows 是所有系列共用的数据行。</td></tr><tr><td><code>CartesianSeriesData</code></td><td>接口</td><td>直角坐标图的一条系列。</td></tr><tr><td><code>chartData</code></td><td>函数</td><td>把查询结果整成图表的数据。</td></tr><tr><td><code>ChartData</code></td><td>类型</td><td>交给图表渲染的数据，形状随图表类型。</td></tr><tr><td><code>DateHeatmapData</code></td><td>接口</td><td>日期热力图的数据：每天一格，日期写 YYYY-MM-DD。</td></tr><tr><td><code>HierarchyChartData</code></td><td>接口</td><td>层级图的数据：扁平的节点表，次序是父在子前。</td></tr><tr><td><code>HierarchyNodeData</code></td><td>接口</td><td>层级图的一个节点：根节点的 parent 为 null，叶子带数值。</td></tr><tr><td><code>MatrixHeatmapData</code></td><td>接口</td><td>矩阵热力图的数据：行与列按首次出现的次序。</td></tr><tr><td><code>RowsChartData</code></td><td>接口</td><td>饼图、漏斗图、雷达图的数据：查询行原样使用，字段按规格取。</td></tr><tr><td><code>SankeyChartData</code></td><td>接口</td><td>桑基图的数据：节点按首次出现的次序，同值的源与目标是同一个节点。</td></tr></tbody></table><h3 id="engine-compute" tabindex="-1">engine/compute <a class="header-anchor" href="#engine-compute" aria-label="Permalink to “engine/compute”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>CardResult</code></td><td>接口</td><td>一张卡片的计算结果：value 的形状由种类定，内置的图表是 ChartData、指标是 MetricValue、表格是 ViewResult。</td></tr><tr><td><code>computeCard</code></td><td>函数</td><td>按种类计算一张卡片：先按取数形状跑查询或视图，再交给种类的 compute。</td></tr><tr><td><code>computeExtensionView</code></td><td>函数</td><td>按种类计算作主体的扩展视图，规则同 computeCard。</td></tr><tr><td><code>computeView</code></td><td>函数</td><td>按视图类型计算明细表、分组报表或交叉表。</td></tr><tr><td><code>ExtensionViewResult</code></td><td>接口</td><td>作主体的扩展视图的计算结果：value 的形状由种类定。</td></tr><tr><td><code>ViewResult</code></td><td>类型</td><td>一个数据视图的计算结果。</td></tr></tbody></table><h3 id="engine-context" tabindex="-1">engine/context <a class="header-anchor" href="#engine-context" aria-label="Permalink to “engine/context”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>ComputeEnvironment</code></td><td>接口</td><td>一次计算的环境。</td></tr><tr><td><code>ComputeOptions</code></td><td>接口</td><td>计算选项。</td></tr></tbody></table><h3 id="engine-crosstab" tabindex="-1">engine/crosstab <a class="header-anchor" href="#engine-crosstab" aria-label="Permalink to “engine/crosstab”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>buildCrosstab</code></td><td>函数</td><td>计算交叉表：行维度与列维度交叉，每格写各度量的聚合值。</td></tr><tr><td><code>CrosstabHeader</code></td><td>接口</td><td>交叉表一条轴上的一项。</td></tr><tr><td><code>CrosstabResult</code></td><td>接口</td><td>交叉表的计算结果。</td></tr></tbody></table><h3 id="engine-crosstab-axis" tabindex="-1">engine/crosstab-axis <a class="header-anchor" href="#engine-crosstab-axis" aria-label="Permalink to “engine/crosstab-axis”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>crosstabAxes</code></td><td>函数</td><td>交叉表两条轴的表头结构。</td></tr><tr><td><code>CrosstabAxes</code></td><td>接口</td><td>交叉表两条轴的表头结构。</td></tr><tr><td><code>CrosstabAxis</code></td><td>接口</td><td>一条轴的表头结构。</td></tr><tr><td><code>CrosstabAxisNode</code></td><td>接口</td><td>表头树的一个节点：一个标签占一格或合并的一片。</td></tr><tr><td><code>CrosstabLabel</code></td><td>类型</td><td>表头上的一个标签；id 相同的相邻标签合成一格。</td></tr><tr><td><code>CrosstabLeaf</code></td><td>接口</td><td>轴上的一个叶子：交叉表的一行或一列。</td></tr></tbody></table><h3 id="engine-cube" tabindex="-1">engine/cube <a class="header-anchor" href="#engine-cube" aria-label="Permalink to “engine/cube”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>isAggregateMeasure</code></td><td>函数</td><td>度量是否为聚合度量。</td></tr></tbody></table><h3 id="engine-dashboard" tabindex="-1">engine/dashboard <a class="header-anchor" href="#engine-dashboard" aria-label="Permalink to “engine/dashboard”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>cardDimension</code></td><td>函数</td><td>卡片上的一个维度：图表与指标卡片是查询的维度，表格卡片按视图类型是明细表的列、分组报表的分组、交叉表的行列维度。</td></tr><tr><td><code>CardDimension</code></td><td>接口</td><td>卡片上一个可发出取值的维度。</td></tr><tr><td><code>computeMetric</code></td><td>函数</td><td>指标卡片的取值：从查询总计里取 value 与 baseline，比出涨跌与变化率。</td></tr><tr><td><code>findCard</code></td><td>函数</td><td>按 id 找卡片。</td></tr><tr><td><code>LinkSelections</code></td><td>类型</td><td>联动的选中值：联动 id 到源维度上选中的取值；空数组或缺项表示没有选中。</td></tr><tr><td><code>MetricResult</code></td><td>接口</td><td>指标卡片的取值。</td></tr><tr><td><code>resolveLinkFilters</code></td><td>函数</td><td>把联动的选中值换成各目标卡片的筛选条件：每个目标得到 field in 选中值，源维度带日期粒度时条件带同一粒度。</td></tr></tbody></table><h3 id="engine-date" tabindex="-1">engine/date <a class="header-anchor" href="#engine-date" aria-label="Permalink to “engine/date”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>createDateTools</code></td><td>函数</td><td>建一组绑定时区的日期工具。</td></tr><tr><td><code>DateTools</code></td><td>接口</td><td>绑定了时区的日期工具。</td></tr></tbody></table><h3 id="engine-errors" tabindex="-1">engine/errors <a class="header-anchor" href="#engine-errors" aria-label="Permalink to “engine/errors”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>ComputeErrorCode</code></td><td>类型</td><td>计算错误码。</td></tr><tr><td><code>ReportComputeError</code></td><td>类</td><td>计算错误：message 即错误码，定位与取值放在 params 里。</td></tr></tbody></table><h3 id="engine-filter" tabindex="-1">engine/filter <a class="header-anchor" href="#engine-filter" aria-label="Permalink to “engine/filter”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>compileFilter</code></td><td>函数</td><td>把筛选编译成行谓词。</td></tr><tr><td><code>FilterEnvironment</code></td><td>接口</td><td>编译筛选需要的环境。</td></tr><tr><td><code>isEmptyOperand</code></td><td>函数</td><td>操作数为空：缺失值，或去掉缺失元素后为空的数组。</td></tr><tr><td><code>isFilterGroup</code></td><td>函数</td><td>判断一个节点是否为子组。</td></tr><tr><td><code>resolveOperand</code></td><td>函数</td><td>操作数的值：参数引用取参数值，未给值的参数为 undefined。</td></tr><tr><td><code>RowPredicate</code></td><td>类型</td><td>行谓词。</td></tr></tbody></table><h3 id="engine-formula" tabindex="-1">engine/formula <a class="header-anchor" href="#engine-formula" aria-label="Permalink to “engine/formula”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>applyCalculatedFields</code></td><td>函数</td><td>给每行算出计算字段，返回新的行数组；数据集没有计算字段时原样返回。</td></tr></tbody></table><h3 id="engine-parameters" tabindex="-1">engine/parameters <a class="header-anchor" href="#engine-parameters" aria-label="Permalink to “engine/parameters”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>PARAMETER_ISSUE_CODES</code></td><td>常量</td><td>参数取值的问题码。</td></tr><tr><td><code>ParameterIssueCode</code></td><td>类型</td><td>参数取值的问题码。</td></tr><tr><td><code>ResolvedParameters</code></td><td>接口</td><td>解析后的参数取值。</td></tr><tr><td><code>resolveParameters</code></td><td>函数</td><td>解析报表参数的取值：输入里没有的参数取缺省值，输入写 null 表示不给值。</td></tr></tbody></table><h3 id="engine-query" tabindex="-1">engine/query <a class="header-anchor" href="#engine-query" aria-label="Permalink to “engine/query”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>QueryResult</code></td><td>接口</td><td>查询结果。</td></tr><tr><td><code>runQuery</code></td><td>函数</td><td>执行聚合查询。</td></tr></tbody></table><h3 id="engine-request" tabindex="-1">engine/request <a class="header-anchor" href="#engine-request" aria-label="Permalink to “engine/request”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>createDatasetRequest</code></td><td>函数</td><td>生成取数请求。</td></tr><tr><td><code>findDataset</code></td><td>函数</td><td>按 id 找数据集。</td></tr><tr><td><code>RequestOptions</code></td><td>接口</td><td>生成取数请求的选项。</td></tr><tr><td><code>RequestSource</code></td><td>类型</td><td>取数的来源：明细表、分组报表、交叉表，或带查询的卡片与扩展视图。</td></tr></tbody></table><h3 id="engine-sort" tabindex="-1">engine/sort <a class="header-anchor" href="#engine-sort" aria-label="Permalink to “engine/sort”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>sortRows</code></td><td>函数</td><td>按明细排序规则排序行，返回新数组。</td></tr></tbody></table><h3 id="engine-table" tabindex="-1">engine/table <a class="header-anchor" href="#engine-table" aria-label="Permalink to “engine/table”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>buildGroupReport</code></td><td>函数</td><td>计算分组报表：逐级分组，每组算出带汇总的列的小计。</td></tr><tr><td><code>buildTable</code></td><td>函数</td><td>计算明细表：算出计算字段、筛选、排序、汇总，再截取。</td></tr><tr><td><code>GroupNode</code></td><td>接口</td><td>分组报表里的一个组。</td></tr><tr><td><code>GroupReportResult</code></td><td>接口</td><td>分组报表的计算结果。</td></tr><tr><td><code>TableResult</code></td><td>接口</td><td>明细表的计算结果。</td></tr></tbody></table><h3 id="expression" tabindex="-1">expression <a class="header-anchor" href="#expression" aria-label="Permalink to “expression”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>CompiledExpression</code></td><td>类型</td><td>转导出自 @xihan-ui/expression</td></tr><tr><td><code>EngineCompileOptions</code></td><td>类型</td><td>转导出自 @xihan-ui/expression</td></tr><tr><td><code>EngineCompileResult</code></td><td>类型</td><td>转导出自 @xihan-ui/expression</td></tr><tr><td><code>EngineEvaluation</code></td><td>类型</td><td>转导出自 @xihan-ui/expression</td></tr><tr><td><code>ExpressionEngine</code></td><td>类型</td><td>转导出自 @xihan-ui/expression</td></tr><tr><td><code>ExpressionIssue</code></td><td>类型</td><td>转导出自 @xihan-ui/expression</td></tr></tbody></table><h3 id="extensions" tabindex="-1">extensions <a class="header-anchor" href="#extensions" aria-label="Permalink to “extensions”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>createReportModel</code></td><td>函数</td><td>合出报表模型：内置扩展 REPORT_CORE_EXTENSION 在前，extensions 按顺序在后。</td></tr><tr><td><code>MetricValue</code></td><td>接口</td><td>指标卡片的计算结果。</td></tr><tr><td><code>REPORT_CORE_EXTENSION</code></td><td>常量</td><td>内置的卡片、主体视图与编辑方式。</td></tr><tr><td><code>REPORT_CORE_EXTENSION_ID</code></td><td>常量</td><td>内置扩展的 id。</td></tr><tr><td><code>REPORT_EXTENSION_SPACES</code></td><td>常量</td><td>报表各层扩展共用的名字空间：卡片种类、视图种类、追加属性与文档级属性的路径。</td></tr><tr><td><code>ReportCardData</code></td><td>类型</td><td>卡片种类的取数形状：query 同图表与指标卡片（卡片上有 dataset、parameters 与 query），view 同表格卡片（带一个明细表、分组报表或交叉表），none 不取数。</td></tr><tr><td><code>ReportCardKind</code></td><td>接口</td><td>一种卡片。</td></tr><tr><td><code>ReportCoreExtension</code></td><td>接口</td><td>报表 core 层的扩展。</td></tr><tr><td><code>ReportKindCheck</code></td><td>接口</td><td>种类校验拿到的上下文：公共字段与取数部分 core 已经查过。</td></tr><tr><td><code>ReportKindEntry</code></td><td>接口</td><td>合并后的一个种类：定义、登记它的扩展 id，以及是不是内置的。</td></tr><tr><td><code>ReportKindInput</code></td><td>接口</td><td>交给种类计算的取数结果：query 形状是查询结果，view 形状是视图结果，none 两者都没有。</td></tr><tr><td><code>ReportModel</code></td><td>接口</td><td>一组扩展合出的报表模型。</td></tr><tr><td><code>ReportPropertyTarget</code></td><td>类型</td><td>属性追加到哪一类对象上：document 之外的键同属性面板的分区——dashboard、card:&lt;种类&gt;、chart:&lt;图表类型&gt;、series、metric、view:&lt;视图类型&gt;、column、group-level、dimension、measure、field、parameter、link。</td></tr><tr><td><code>ReportQueryIds</code></td><td>接口</td><td>卡片查询里现有的维度与度量 id，按查询里的先后。</td></tr><tr><td><code>ReportRuleContext</code></td><td>接口</td><td>规则拿到的上下文：合并后的报表模型。</td></tr><tr><td><code>ReportViewData</code></td><td>类型</td><td>主体视图种类的取数形状：扩展视图只能是 query 或 none；table、group、crosstab、dashboard 是内置四种自己的形状。</td></tr><tr><td><code>ReportViewKind</code></td><td>接口</td><td>一种主体视图。</td></tr></tbody></table><h3 id="grid" tabindex="-1">grid <a class="header-anchor" href="#grid" aria-label="Permalink to “grid”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>CardPlacement</code></td><td>接口</td><td>新增卡片的位置：写了 x、y 时放在那里并推开压到的卡片，没写时放到第一个放得下的空位。</td></tr><tr><td><code>gridItems</code></td><td>函数</td><td>看板上全部卡片的网格位置，次序与卡片相同。</td></tr><tr><td><code>layoutOperations</code></td><td>函数</td><td>把布局的变化写成一条 layoutCards：before 里有、位置大小变了的卡片；没有变化时为空数组。</td></tr><tr><td><code>NewCard</code></td><td>类型</td><td>待新增的卡片：layout 只需写大小，位置可以留给 planAddCard 找空位。</td></tr><tr><td><code>NewExtensionCard</code></td><td>接口</td><td>待新增的扩展卡片：同 ExtensionCard，layout 只需写大小。</td></tr><tr><td><code>planAddCard</code></td><td>函数</td><td>新增卡片：按 placement 放进网格（推开压到的卡片，缺省整体压实），产出 addCard 与其余卡片的 layoutCards。</td></tr><tr><td><code>planCardLayout</code></td><td>函数</td><td>拖动或改大小：把卡片放到 target（只改写了的项），压到的卡片向下推开，向下拖过下方卡片时两者对调，之后缺省整体压实。</td></tr><tr><td><code>planCompactLayout</code></td><td>函数</td><td>压实布局：每张卡片向上移到碰到别的卡片为止，原本重叠的向下推开；没有变化时为空数组。</td></tr><tr><td><code>planRemoveCard</code></td><td>函数</td><td>删除卡片并清理联动：以它为源的联动整条删除，指向它的目标从联动里去掉，目标删空的联动也删除；之后缺省整体压实。</td></tr></tbody></table><h3 id="item-plans" tabindex="-1">item-plans <a class="header-anchor" href="#item-plans" aria-label="Permalink to “item-plans”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>planAddFieldItem</code></td><td>函数</td><td>从数据集字段生成一个列表项并加进列表：维度（查询的 dimensions、交叉表的 rows / columns、分组报表的 groups）取这个字段，日期字段缺省按月分桶；度量里数值字段缺省 sum，其余缺省 count；明细表与分组报表的列只取字段。</td></tr><tr><td><code>planRemoveItem</code></td><td>函数</td><td>删除列表项，并清理对它的引用：以这张卡片为源、在它上面发出取值的联动删除；引用它的直角坐标系列删除，雷达指标与层级从数组里去掉，可选的引用（splitBy、气泡大小与颜色、指标基准值）删掉属性，引用它的迷你图删掉；查询排序的规则与各处的 sort.by 去掉，标注里指向被删系列的去掉。</td></tr><tr><td><code>planRenameField</code></td><td>函数</td><td>字段改名：updateField，并把绑定这个数据集的视图与查询里引用它的地方一起改掉——列、分组、维度与度量的 field，筛选条件与明细排序的 field、目标卡片绑定这个数据集的联动目标的 field，以及同一数据集里计算字段公式对它的引用。</td></tr><tr><td><code>planRenameItem</code></td><td>函数</td><td>列表项改 id：updateItem，并把别处对它的引用一起改掉——图表与指标配置里引用它的字段、查询排序的 key 与维度排序的 by、分组的 sort.by（列）、交叉表维度的 sort.by（度量）、直角坐标图标注的 series，以及以这张卡片为源、在它上面发出取值的联动。</td></tr></tbody></table><h3 id="operations-apply" tabindex="-1">operations/apply <a class="header-anchor" href="#operations-apply" aria-label="Permalink to “operations/apply”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>applyOperation</code></td><td>函数</td><td>以纯函数方式执行编辑操作：不修改传入的文档，返回新文档与逆操作数组；没有改到的部分沿用原引用。</td></tr><tr><td><code>applyOperations</code></td><td>函数</td><td>按顺序执行一组编辑操作，整体成功或整体失败（@xihan-ui/designer-kit 的 applyInSequence）；逆操作为各操作逆操作按相反顺序的拼接。</td></tr></tbody></table><h3 id="operations-describe" tabindex="-1">operations/describe <a class="header-anchor" href="#operations-describe" aria-label="Permalink to “operations/describe”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>describeReportStep</code></td><td>函数</td><td>撤销栈里一步的说明素材：按第一个操作定动作与对象种类，同一步里同动作、同种类的操作合起来计个数；只改了一个对象时带上它的名字（标题，没有时取 id 或字段名）。</td></tr><tr><td><code>ReportStep</code></td><td>接口</td><td>一步的说明素材。</td></tr><tr><td><code>ReportStepAction</code></td><td>类型</td><td>一步里的动作。</td></tr><tr><td><code>ReportStepKind</code></td><td>类型</td><td>一步改的对象种类，与设计器文案 objectKinds 的键同一组。</td></tr></tbody></table><h3 id="operations-errors" tabindex="-1">operations/errors <a class="header-anchor" href="#operations-errors" aria-label="Permalink to “operations/errors”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>ReportOperationError</code></td><td>类</td><td>操作无法应用时抛出的错误：message 即错误码，输入文档保持不变。</td></tr><tr><td><code>ReportOperationErrorCode</code></td><td>类型</td><td>操作失败的原因：</td></tr></tbody></table><h3 id="operations-path" tabindex="-1">operations/path <a class="header-anchor" href="#operations-path" aria-label="Permalink to “operations/path”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>itemKey</code></td><td>函数</td><td>数组项的键：id，没有 id 时取 name；都不是字符串时为 undefined。</td></tr><tr><td><code>readPath</code></td><td>函数</td><td>读取路径处的值；路径不存在时为 undefined，路径段不合法（负数、小数、原型键）时抛 JsonPathError。</td></tr></tbody></table><h3 id="operations-types" tabindex="-1">operations/types <a class="header-anchor" href="#operations-types" aria-label="Permalink to “operations/types”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>AddCardOperation</code></td><td>接口</td><td>新增卡片，index 缺省放在末尾；位置大小写在卡片的 layout 里。</td></tr><tr><td><code>AddDatasetOperation</code></td><td>接口</td><td>新增数据集，index 缺省放在末尾。</td></tr><tr><td><code>AddFieldOperation</code></td><td>接口</td><td>在数据集里新增字段，index 缺省放在末尾。</td></tr><tr><td><code>AddItemOperation</code></td><td>接口</td><td>在列表里新增一项，index 缺省放在末尾。</td></tr><tr><td><code>AddLinkOperation</code></td><td>接口</td><td>新增联动，index 缺省放在末尾。</td></tr><tr><td><code>AddParameterOperation</code></td><td>接口</td><td>新增报表参数，index 缺省放在末尾。</td></tr><tr><td><code>ItemList</code></td><td>类型</td><td>视图或查询里的列表：明细表的 columns；分组报表的 groups、columns；交叉表的 rows、columns、measures；图表与指标卡片查询的 dimensions、measures；直角坐标图的 series。</td></tr><tr><td><code>ItemOwner</code></td><td>接口</td><td>列表项的所在：card 缺省时是报表主体的视图；表格卡片是它的视图，图表与指标卡片是它的查询，series 是直角坐标图的配置。</td></tr><tr><td><code>LayoutCardsOperation</code></td><td>接口</td><td>一次改多张卡片的位置大小。</td></tr><tr><td><code>MoveDatasetOperation</code></td><td>接口</td><td>把数据集移到 index。</td></tr><tr><td><code>MoveFieldOperation</code></td><td>接口</td><td>把数据集里的字段移到 index。</td></tr><tr><td><code>MoveItemOperation</code></td><td>接口</td><td>把列表项移到 index；写了 to 时移到同一视图的另一个列表，如交叉表的行维度换到列维度。</td></tr><tr><td><code>MoveParameterOperation</code></td><td>接口</td><td>把报表参数移到 index。</td></tr><tr><td><code>PropertyChange</code></td><td>接口</td><td>一处属性修改：path 相对被修改的对象，写法同 ReportPath；value 不写表示删除该属性。</td></tr><tr><td><code>RemoveCardOperation</code></td><td>接口</td><td>删除卡片；引用它的联动不随之改动，用 planRemoveCard 一并清理。</td></tr><tr><td><code>RemoveDatasetOperation</code></td><td>接口</td><td>删除数据集；用着它的卡片、视图与联动不一并改，要连带删除时用 planRemoveDataset。</td></tr><tr><td><code>RemoveFieldOperation</code></td><td>接口</td><td>删除数据集里的字段；引用它的地方不一并改，要连带删除时用 planRemoveField。</td></tr><tr><td><code>RemoveItemOperation</code></td><td>接口</td><td>删除报表主体或卡片里某个列表的一项。</td></tr><tr><td><code>RemoveLinkOperation</code></td><td>接口</td><td>删除看板的联动。</td></tr><tr><td><code>RemoveParameterOperation</code></td><td>接口</td><td>删除报表参数；引用它的地方不一并改，要连带删除时用 planRemoveParameter。</td></tr><tr><td><code>ReplaceDocumentOperation</code></td><td>接口</td><td>整份换掉报表定义，如编辑整份 JSON 之后应用。</td></tr><tr><td><code>ReportOperation</code></td><td>类型</td><td>编辑操作。</td></tr><tr><td><code>ReportOperationResult</code></td><td>类型</td><td>操作结果，即 @xihan-ui/designer-kit 的 OperationResult：新文档，以及按顺序作用于新文档即可还原出传入文档的逆操作。</td></tr><tr><td><code>ReportOperationType</code></td><td>类型</td><td>编辑操作的种类。</td></tr><tr><td><code>ReportPath</code></td><td>类型</td><td>报表里的路径：字符串段是对象的属性名，或数组里带 id（没有 id 时取 name）的那一项；数字段是数组下标。</td></tr><tr><td><code>SetBodyOperation</code></td><td>接口</td><td>换掉报表主体，用来改报表的类型。</td></tr><tr><td><code>UpdateCardOperation</code></td><td>接口</td><td>修改卡片；不能修改 id、kind 与 layout（位置大小用 layoutCards）。</td></tr><tr><td><code>UpdateDashboardOperation</code></td><td>接口</td><td>修改看板本身（网格）；不能修改 type、cards 与 links。</td></tr><tr><td><code>UpdateDatasetOperation</code></td><td>接口</td><td>修改数据集；不能修改 id 与 fields（字段用字段的操作）。</td></tr><tr><td><code>UpdateDocumentOperation</code></td><td>接口</td><td>修改文档本身的属性；不能修改 schemaVersion、datasets、parameters 与 body。</td></tr><tr><td><code>UpdateFieldOperation</code></td><td>接口</td><td>修改字段；可以改 name，同一数据集里不能重名。</td></tr><tr><td><code>UpdateItemOperation</code></td><td>接口</td><td>修改列表项；可以改 id，同一列表里不能重复。</td></tr><tr><td><code>UpdateLinkOperation</code></td><td>接口</td><td>修改联动；不能修改 id。</td></tr><tr><td><code>UpdateParameterOperation</code></td><td>接口</td><td>修改报表参数；可以改 name，不能与别的参数重名。</td></tr><tr><td><code>UpdateViewOperation</code></td><td>接口</td><td>修改视图：card 缺省时是报表主体（须是明细表、分组报表或交叉表），否则是那张表格卡片的视图；不能修改 type。</td></tr></tbody></table><h3 id="properties" tabindex="-1">properties <a class="header-anchor" href="#properties" aria-label="Permalink to “properties”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>builtinProperties</code></td><td>函数</td><td>某类对象的内置属性；扩展追加的属性不能与它们同路径。</td></tr><tr><td><code>cardProperties</code></td><td>函数</td><td>卡片自身的属性：标题、说明；带查询的卡片（图表、指标，或取数形状为 query 的扩展卡片）还有数据集、参数绑定与查询的筛选、行数上限。</td></tr><tr><td><code>chartProperties</code></td><td>函数</td><td>图表配置的属性，路径相对图表配置；直角坐标图的系列另用 seriesProperties。</td></tr><tr><td><code>dashboardProperties</code></td><td>函数</td><td>看板本身的属性：网格的列数与行高（px）。</td></tr><tr><td><code>datasetFieldProperties</code></td><td>函数</td><td>数据集一个字段的属性，路径相对字段。</td></tr><tr><td><code>dimensionProperties</code></td><td>函数</td><td>查询或交叉表一个维度的属性，路径相对维度。</td></tr><tr><td><code>documentProperties</code></td><td>函数</td><td>报表文档的属性：标题与说明。</td></tr><tr><td><code>extensionViewProperties</code></td><td>函数</td><td>作主体的扩展视图的属性：取数形状为 query 时是取数属性，none 时没有。</td></tr><tr><td><code>groupLevelProperties</code></td><td>函数</td><td>分组报表一级分组的属性，路径相对分组。</td></tr><tr><td><code>linkProperties</code></td><td>函数</td><td>看板联动的属性，路径相对联动。</td></tr><tr><td><code>measureProperties</code></td><td>函数</td><td>一个度量的属性，路径相对度量：写了 formula 的是公式度量，否则是聚合度量。</td></tr><tr><td><code>metricProperties</code></td><td>函数</td><td>指标卡片配置的属性，路径相对指标配置；迷你图的属性只在写了迷你图时显示。</td></tr><tr><td><code>parameterProperties</code></td><td>函数</td><td>报表参数的属性，路径相对参数。</td></tr><tr><td><code>REPORT_PROPERTY_GROUPS</code></td><td>常量</td><td>属性分组的先后。</td></tr><tr><td><code>ReportPropertyControl</code></td><td>类型</td><td>报表的编辑方式：designer-kit 的内建方式，加上报表自己的几种。</td></tr><tr><td><code>ReportPropertyDescriptor</code></td><td>类型</td><td>报表的属性描述。</td></tr><tr><td><code>ReportPropertyGroup</code></td><td>类型</td><td>属性分组。</td></tr><tr><td><code>seriesProperties</code></td><td>函数</td><td>直角坐标图一个系列的属性，路径相对系列；各标记的专有属性只在该标记下显示。</td></tr><tr><td><code>tableColumnProperties</code></td><td>函数</td><td>明细表与分组报表一列的属性，路径相对列；汇总写聚合或公式之一。</td></tr><tr><td><code>viewProperties</code></td><td>函数</td><td>视图的属性，路径相对视图（报表主体或表格卡片的 view）；列表里的项另用各自的描述。</td></tr></tbody></table><h3 id="schema-chart" tabindex="-1">schema/chart <a class="header-anchor" href="#schema-chart" aria-label="Permalink to “schema/chart”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>CartesianAnnotationSpec</code></td><td>类型</td><td>注释；axis 的 x 是自变量轴，y 是数值轴。</td></tr><tr><td><code>CartesianAxisSpec</code></td><td>接口</td><td>坐标轴；时间值写 ISO 8601 字符串。</td></tr><tr><td><code>CartesianBarSeriesSpec</code></td><td>接口</td><td>柱系列。</td></tr><tr><td><code>CartesianChartSpec</code></td><td>接口</td><td>笛卡尔图：柱、折线、面积、散点。</td></tr><tr><td><code>CartesianLineSeriesSpec</code></td><td>接口</td><td>折线系列。</td></tr><tr><td><code>CartesianScatterSeriesSpec</code></td><td>接口</td><td>散点系列：每个维度组合一个点。</td></tr><tr><td><code>CartesianSeriesSpec</code></td><td>类型</td><td>柱线图的一条系列：柱、折线或散点。</td></tr><tr><td><code>CartesianSeriesSpecBase</code></td><td>接口</td><td>笛卡尔图系列的共有属性。</td></tr><tr><td><code>CHART_TYPES</code></td><td>常量</td><td>全部图表类型。</td></tr><tr><td><code>ChartPalette</code></td><td>类型</td><td>顺序色阶的色板，与 XiHan.UI 的 ChartPalette 一致。</td></tr><tr><td><code>ChartSize</code></td><td>类型</td><td>尺寸档。</td></tr><tr><td><code>ChartSpec</code></td><td>类型</td><td>图表配置，按 type 分。</td></tr><tr><td><code>ChartSymbol</code></td><td>类型</td><td>散点形状：XiHan.UI 图表引擎的 SymbolName。</td></tr><tr><td><code>ChartTone</code></td><td>类型</td><td>语气：XiHan.UI 的 Tone。</td></tr><tr><td><code>FunnelChartSpec</code></td><td>接口</td><td>漏斗图：每个维度成员一个阶段。</td></tr><tr><td><code>HeatmapChartSpec</code></td><td>类型</td><td>热力图：日历（含按月）或矩阵。</td></tr><tr><td><code>HeatmapChartSpecBase</code></td><td>接口</td><td>热力图共有的属性。</td></tr><tr><td><code>HeatmapDateChartSpec</code></td><td>接口</td><td>日期热力图：calendar 连续周列，month 按自然月分块。</td></tr><tr><td><code>HeatmapMatrixChartSpec</code></td><td>接口</td><td>矩阵热力图：行列各是一个维度。</td></tr><tr><td><code>HierarchyChartSpec</code></td><td>接口</td><td>层级图：维度依次是由上到下的层。</td></tr><tr><td><code>MetricSpec</code></td><td>接口</td><td>指标卡片：一个汇总值，可带对比与走势。</td></tr><tr><td><code>PieChartSpec</code></td><td>接口</td><td>饼图：每个维度成员一个扇区。</td></tr><tr><td><code>RadarChartSpec</code></td><td>接口</td><td>雷达图：每个维度成员一个实体，每个指标一根轴。</td></tr><tr><td><code>RadarIndicatorSpec</code></td><td>接口</td><td>雷达图的一个指标。</td></tr><tr><td><code>SankeyChartSpec</code></td><td>接口</td><td>桑基图：每个维度组合一条流带。</td></tr><tr><td><code>SparklineSpec</code></td><td>接口</td><td>迷你图：指标卡片里的走势。</td></tr></tbody></table><h3 id="schema-dataset" tabindex="-1">schema/dataset <a class="header-anchor" href="#schema-dataset" aria-label="Permalink to “schema/dataset”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>DatasetAggregated</code></td><td>接口</td><td>已聚合数据：使用方按请求里的 query 在后端聚合并筛选过。</td></tr><tr><td><code>DatasetData</code></td><td>类型</td><td>使用方交回的数据。</td></tr><tr><td><code>DatasetField</code></td><td>接口</td><td>数据集里的一个字段。</td></tr><tr><td><code>DatasetParameter</code></td><td>接口</td><td>数据集接受的一个参数：取数时由使用方的数据源解释。</td></tr><tr><td><code>DatasetQuery</code></td><td>接口</td><td>视图需要的聚合：使用方可以照此在后端聚合，返回 aggregated 数据。</td></tr><tr><td><code>DatasetQueryDimension</code></td><td>接口</td><td>取数请求里的一个维度：按 field 分组，写了 bucket 时按日期粒度取键。</td></tr><tr><td><code>DatasetQueryMeasure</code></td><td>接口</td><td>取数请求里的一个度量：对 field 做 aggregate；count 不写 field 时数行。</td></tr><tr><td><code>DatasetRequest</code></td><td>接口</td><td>取数请求：core 按视图与参数取值算出，使用方据此取数。</td></tr><tr><td><code>DatasetRollup</code></td><td>接口</td><td>一条汇总行：按 dimensions 分组的汇总值，键同已聚合行。</td></tr><tr><td><code>DatasetRows</code></td><td>接口</td><td>明细行：core 负责计算字段、筛选、分组与聚合。</td></tr><tr><td><code>DatasetSchema</code></td><td>接口</td><td>报表引用的一个数据集。</td></tr></tbody></table><h3 id="schema-document" tabindex="-1">schema/document <a class="header-anchor" href="#schema-document" aria-label="Permalink to “schema/document”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>ParameterOption</code></td><td>接口</td><td>参数的一个候选项。</td></tr><tr><td><code>REPORT_SCHEMA_VERSION</code></td><td>常量</td><td>当前的 schema 版本。</td></tr><tr><td><code>ReportDocument</code></td><td>接口</td><td>报表文档：纯 JSON。</td></tr><tr><td><code>ReportParameter</code></td><td>接口</td><td>报表参数：报表使用者填写，经绑定传给数据集参数或筛选条件。</td></tr></tbody></table><h3 id="schema-extension" tabindex="-1">schema/extension <a class="header-anchor" href="#schema-extension" aria-label="Permalink to “schema/extension”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>ReportExtensible</code></td><td>接口</td><td>能带扩展数据的对象：文档、数据集、字段、参数、视图、卡片、各列表项与联动。</td></tr><tr><td><code>ReportExtensionData</code></td><td>类型</td><td>对象上各扩展自己的数据：键是扩展 id，值归那个扩展；校验只查它与每一块都是对象，里面不看。</td></tr><tr><td><code>ReportExtensionKind</code></td><td>类型</td><td>扩展登记的卡片与视图种类名：扩展 id 的末段、一个点、名字，如 gantt.timeline。</td></tr></tbody></table><h3 id="schema-filter" tabindex="-1">schema/filter <a class="header-anchor" href="#schema-filter" aria-label="Permalink to “schema/filter”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>FILTER_OPERATORS</code></td><td>常量</td><td>转导出自 @xihan-ui/viz</td></tr><tr><td><code>FilterCondition</code></td><td>接口</td><td>一个筛选条件。</td></tr><tr><td><code>FilterGroup</code></td><td>接口</td><td>条件组：and 全部满足，or 任一满足。</td></tr><tr><td><code>FilterNode</code></td><td>类型</td><td>条件组里的一项：条件或子组。</td></tr><tr><td><code>FilterOperator</code></td><td>类型</td><td>转导出自 @xihan-ui/viz</td></tr><tr><td><code>FilterSubgroup</code></td><td>接口</td><td>嵌套在条件组里的子组。</td></tr><tr><td><code>NullsPosition</code></td><td>类型</td><td>转导出自 @xihan-ui/viz</td></tr><tr><td><code>Operand</code></td><td>类型</td><td>操作数：字面值、字面值数组，或报表参数。</td></tr><tr><td><code>ParameterRef</code></td><td>接口</td><td>引用一个报表参数的值。</td></tr><tr><td><code>RowSortRule</code></td><td>接口</td><td>明细行的一条排序规则。</td></tr><tr><td><code>SortDirection</code></td><td>类型</td><td>转导出自 @xihan-ui/viz</td></tr></tbody></table><h3 id="schema-format" tabindex="-1">schema/format <a class="header-anchor" href="#schema-format" aria-label="Permalink to “schema/format”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>DateFormatSpec</code></td><td>类型</td><td>转导出自 @xihan-ui/expression</td></tr><tr><td><code>FormatRounding</code></td><td>类型</td><td>转导出自 @xihan-ui/expression</td></tr><tr><td><code>FormatSpec</code></td><td>类型</td><td>转导出自 @xihan-ui/expression</td></tr><tr><td><code>NumberFormatSpec</code></td><td>类型</td><td>转导出自 @xihan-ui/expression</td></tr><tr><td><code>NumericFormatSpec</code></td><td>类型</td><td>图表数值用的格式说明：数字或百分比。</td></tr><tr><td><code>PercentFormatSpec</code></td><td>类型</td><td>转导出自 @xihan-ui/expression</td></tr><tr><td><code>RmbUpperFormatSpec</code></td><td>类型</td><td>转导出自 @xihan-ui/expression</td></tr></tbody></table><h3 id="schema-options" tabindex="-1">schema/options <a class="header-anchor" href="#schema-options" aria-label="Permalink to “schema/options”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>ANNOTATION_AXES</code></td><td>常量</td><td>取值：<code>x</code>、<code>y</code>。</td></tr><tr><td><code>ANNOTATION_KINDS</code></td><td>常量</td><td>取值：<code>line</code>、<code>band</code>、<code>point</code>、<code>average</code>、<code>trend</code>。</td></tr><tr><td><code>ANNOTATION_POINTS</code></td><td>常量</td><td>取值：<code>max</code>、<code>min</code>、<code>last</code>。</td></tr><tr><td><code>AXIS_FITS</code></td><td>常量</td><td>取值：<code>all</code>、<code>window</code>。</td></tr><tr><td><code>AXIS_LABEL_OVERFLOWS</code></td><td>常量</td><td>取值：<code>auto</code>、<code>rotate</code>、<code>truncate</code>、<code>wrap</code>。</td></tr><tr><td><code>AXIS_SCALES</code></td><td>常量</td><td>取值：<code>band</code>、<code>point</code>、<code>linear</code>、<code>log</code>、<code>sqrt</code>、<code>pow</code>、<code>symlog</code>、<code>time</code>、<code>utc</code>。</td></tr><tr><td><code>BAR_LABELS</code></td><td>常量</td><td>取值：<code>none</code>、<code>inside</code>、<code>end</code>。</td></tr><tr><td><code>BAR_SHAPES</code></td><td>常量</td><td>取值：<code>bar</code>、<code>lollipop</code>。</td></tr><tr><td><code>BAR_STACK_OFFSETS</code></td><td>常量</td><td>取值：<code>none</code>、<code>expand</code>、<code>diverging</code>。</td></tr><tr><td><code>CARD_KINDS</code></td><td>常量</td><td>取值：<code>chart</code>、<code>metric</code>、<code>table</code>。</td></tr><tr><td><code>CARTESIAN_ORIENTATIONS</code></td><td>常量</td><td>取值：<code>vertical</code>、<code>horizontal</code>。</td></tr><tr><td><code>CHART_INTERACTION_AXES</code></td><td>常量</td><td>缩放与刷选的方向。</td></tr><tr><td><code>CHART_PALETTES</code></td><td>常量</td><td>取值：<code>red</code>、<code>orange</code>、<code>amber</code>、<code>yellow</code>、<code>lime</code>、<code>green</code>、<code>teal</code>、<code>cyan</code>、<code>blue</code>、<code>indigo</code>、<code>purple</code>、<code>pink</code>、<code>gray</code>。</td></tr><tr><td><code>CHART_RENDERERS</code></td><td>常量</td><td>取值：<code>svg</code>、<code>canvas</code>、<code>auto</code>。</td></tr><tr><td><code>CHART_SIZES</code></td><td>常量</td><td>取值：<code>sm</code>、<code>md</code>、<code>lg</code>。</td></tr><tr><td><code>CHART_TONES</code></td><td>常量</td><td>取值：<code>brand</code>、<code>neutral</code>、<code>success</code>、<code>warning</code>、<code>danger</code>、<code>info</code>。</td></tr><tr><td><code>CHART_TRIGGERS</code></td><td>常量</td><td>取值：<code>axis</code>、<code>item</code>。</td></tr><tr><td><code>COLUMN_ALIGNS</code></td><td>常量</td><td>取值：<code>start</code>、<code>center</code>、<code>end</code>。</td></tr><tr><td><code>COLUMN_STICKY_SIDES</code></td><td>常量</td><td>取值：<code>start</code>、<code>end</code>。</td></tr><tr><td><code>FILTER_LOGICS</code></td><td>常量</td><td>取值：<code>and</code>、<code>or</code>。</td></tr><tr><td><code>FUNNEL_ALIGNS</code></td><td>常量</td><td>取值：<code>center</code>、<code>start</code>。</td></tr><tr><td><code>FUNNEL_CONVERSIONS</code></td><td>常量</td><td>取值：<code>previous</code>、<code>first</code>、<code>none</code>。</td></tr><tr><td><code>FUNNEL_DIRECTIONS</code></td><td>常量</td><td>取值：<code>down</code>、<code>up</code>。</td></tr><tr><td><code>FUNNEL_LABELS</code></td><td>常量</td><td>取值：<code>inside</code>、<code>outside</code>。</td></tr><tr><td><code>FUNNEL_SHAPES</code></td><td>常量</td><td>取值：<code>trapezoid</code>、<code>bar</code>。</td></tr><tr><td><code>HEATMAP_SCALES</code></td><td>常量</td><td>取值：<code>sequential</code>、<code>diverging</code>。</td></tr><tr><td><code>HEATMAP_VARIANTS</code></td><td>常量</td><td>取值：<code>calendar</code>、<code>month</code>、<code>matrix</code>。</td></tr><tr><td><code>HIERARCHY_COLOR_BY</code></td><td>常量</td><td>取值：<code>branch</code>、<code>value</code>、<code>uniform</code>。</td></tr><tr><td><code>HIERARCHY_LAYOUTS</code></td><td>常量</td><td>取值：<code>treemap</code>、<code>sunburst</code>、<code>icicle</code>、<code>pack</code>。</td></tr><tr><td><code>HIERARCHY_ORIENTATIONS</code></td><td>常量</td><td>取值：<code>vertical</code>、<code>horizontal</code>。</td></tr><tr><td><code>HIERARCHY_TILES</code></td><td>常量</td><td>取值：<code>squarify</code>、<code>binary</code>、<code>slice-dice</code>。</td></tr><tr><td><code>LINE_CURVES</code></td><td>常量</td><td>取值：<code>linear</code>、<code>monotone</code>、<code>step</code>、<code>step-before</code>、<code>step-after</code>。</td></tr><tr><td><code>LINE_LABELS</code></td><td>常量</td><td>取值：<code>none</code>、<code>end</code>。</td></tr><tr><td><code>LINE_STACK_OFFSETS</code></td><td>常量</td><td>取值：<code>none</code>、<code>expand</code>、<code>silhouette</code>、<code>wiggle</code>。</td></tr><tr><td><code>LINE_SYMBOLS</code></td><td>常量</td><td>取值：<code>auto</code>、<code>always</code>、<code>none</code>。</td></tr><tr><td><code>MEASURES_ON</code></td><td>常量</td><td>取值：<code>columns</code>、<code>rows</code>。</td></tr><tr><td><code>NULLS_POSITIONS</code></td><td>常量</td><td>取值：<code>first</code>、<code>last</code>。</td></tr><tr><td><code>PIE_LABEL_CONTENTS</code></td><td>常量</td><td>取值：<code>name-share</code>、<code>name-value</code>、<code>name</code>、<code>share</code>、<code>value</code>。</td></tr><tr><td><code>PIE_LABELS</code></td><td>常量</td><td>取值：<code>none</code>、<code>inside</code>、<code>outside</code>。</td></tr><tr><td><code>PIE_SORTS</code></td><td>常量</td><td>取值：<code>none</code>、<code>descending</code>。</td></tr><tr><td><code>PIE_SWEEPS</code></td><td>常量</td><td>取值：<code>full</code>、<code>half</code>。</td></tr><tr><td><code>PIE_VARIANTS</code></td><td>常量</td><td>取值：<code>pie</code>、<code>donut</code>。</td></tr><tr><td><code>RADAR_CURVES</code></td><td>常量</td><td>取值：<code>linear</code>、<code>catmull-rom</code>。</td></tr><tr><td><code>RADAR_SCALES</code></td><td>常量</td><td>取值：<code>shared</code>、<code>independent</code>。</td></tr><tr><td><code>RADAR_SHAPES</code></td><td>常量</td><td>取值：<code>polygon</code>、<code>circle</code>。</td></tr><tr><td><code>SANKEY_LINK_COLORS</code></td><td>常量</td><td>取值：<code>neutral</code>、<code>source</code>、<code>target</code>、<code>gradient</code>。</td></tr><tr><td><code>SANKEY_NODE_ALIGNS</code></td><td>常量</td><td>取值：<code>justify</code>、<code>start</code>、<code>end</code>、<code>center</code>。</td></tr><tr><td><code>SANKEY_NODE_SORTS</code></td><td>常量</td><td>取值：<code>auto</code>、<code>input</code>。</td></tr><tr><td><code>SANKEY_ORIENTATIONS</code></td><td>常量</td><td>取值：<code>horizontal</code>、<code>vertical</code>。</td></tr><tr><td><code>SERIES_MARKS</code></td><td>常量</td><td>取值：<code>bar</code>、<code>line</code>、<code>scatter</code>。</td></tr><tr><td><code>SORT_DIRECTIONS</code></td><td>常量</td><td>取值：<code>asc</code>、<code>desc</code>。</td></tr><tr><td><code>SPARKLINE_CURVES</code></td><td>常量</td><td>取值：<code>linear</code>、<code>monotone</code>。</td></tr><tr><td><code>SPARKLINE_MARKERS</code></td><td>常量</td><td>取值：<code>none</code>、<code>last</code>、<code>extremes</code>。</td></tr><tr><td><code>SPARKLINE_VARIANTS</code></td><td>常量</td><td>取值：<code>line</code>、<code>area</code>、<code>bar</code>、<code>win-loss</code>。</td></tr><tr><td><code>TOOLTIP_ORDERS</code></td><td>常量</td><td>取值：<code>series</code>、<code>descending</code>、<code>ascending</code>。</td></tr><tr><td><code>TREND_METHODS</code></td><td>常量</td><td>取值：<code>linear</code>、<code>moving-average</code>。</td></tr></tbody></table><h3 id="schema-query" tabindex="-1">schema/query <a class="header-anchor" href="#schema-query" aria-label="Permalink to “schema/query”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>AGGREGATE_KINDS</code></td><td>常量</td><td>转导出自 @xihan-ui/viz</td></tr><tr><td><code>AggregateKind</code></td><td>类型</td><td>转导出自 @xihan-ui/viz</td></tr><tr><td><code>AggregateMeasure</code></td><td>接口</td><td>聚合度量：对字段做聚合；count 不写 field 时数行。</td></tr><tr><td><code>AxisSort</code></td><td>接口</td><td>成员的次序：按键，或按某个度量在该成员上的汇总值。</td></tr><tr><td><code>DATE_BUCKETS</code></td><td>常量</td><td>全部日期粒度，由粗到细。</td></tr><tr><td><code>DateBucket</code></td><td>类型</td><td>日期粒度：把日期取成分组键。</td></tr><tr><td><code>Dimension</code></td><td>接口</td><td>维度：按字段分组。</td></tr><tr><td><code>FormulaMeasure</code></td><td>接口</td><td>公式度量：在聚合之后，以同一查询其它度量的值与报表参数（$名字）为变量求值。</td></tr><tr><td><code>Measure</code></td><td>类型</td><td>度量：聚合度量或公式度量。</td></tr><tr><td><code>MeasureBase</code></td><td>接口</td><td>共有的度量属性。</td></tr><tr><td><code>QuerySortRule</code></td><td>接口</td><td>查询结果行的一条排序规则。</td></tr><tr><td><code>ReportQuery</code></td><td>接口</td><td>聚合查询：按维度分组、计算度量，结果每个维度组合一行。</td></tr></tbody></table><h3 id="schema-value" tabindex="-1">schema/value <a class="header-anchor" href="#schema-value" aria-label="Permalink to “schema/value”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>DataRow</code></td><td>类型</td><td>一行数据：字段名到值。</td></tr><tr><td><code>FIELD_TYPES</code></td><td>常量</td><td>全部字段类型，按声明次序。</td></tr><tr><td><code>FieldType</code></td><td>类型</td><td>字段类型。</td></tr><tr><td><code>JsonValue</code></td><td>类型</td><td>转导出自 @xihan-ui/core/json</td></tr><tr><td><code>ParameterValue</code></td><td>类型</td><td>参数的取值：单值，或多选参数的值数组。</td></tr><tr><td><code>ParameterValues</code></td><td>类型</td><td>一组参数取值：参数名到值。</td></tr><tr><td><code>ScalarValue</code></td><td>类型</td><td>JSON 标量：模板里能写下的单个值。</td></tr></tbody></table><h3 id="schema-view" tabindex="-1">schema/view <a class="header-anchor" href="#schema-view" aria-label="Permalink to “schema/view”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>CardBase</code></td><td>接口</td><td>卡片的共有属性。</td></tr><tr><td><code>CardLayout</code></td><td>接口</td><td>卡片在网格上的位置与大小，单位是格。</td></tr><tr><td><code>ChartCard</code></td><td>接口</td><td>图表卡片。</td></tr><tr><td><code>ColumnSummary</code></td><td>类型</td><td>汇总：对列的字段做聚合，或以其它列的汇总值与报表参数（$名字）为变量求公式。</td></tr><tr><td><code>CrosstabTotals</code></td><td>接口</td><td>交叉表一条轴上的汇总。</td></tr><tr><td><code>CrosstabView</code></td><td>接口</td><td>交叉表：行维度与列维度交叉，格子里写度量。</td></tr><tr><td><code>DashboardCard</code></td><td>类型</td><td>看板上的一张卡片：图表、指标、表格，或扩展登记的种类。</td></tr><tr><td><code>DashboardGrid</code></td><td>接口</td><td>看板网格。</td></tr><tr><td><code>DashboardLink</code></td><td>接口</td><td>筛选联动：在源卡片上选中的取值，成为目标卡片在对应字段上的 in 条件。</td></tr><tr><td><code>DashboardView</code></td><td>接口</td><td>看板：网格上排列的卡片。</td></tr><tr><td><code>DataBinding</code></td><td>接口</td><td>视图取数的数据集与参数绑定。</td></tr><tr><td><code>DataView</code></td><td>类型</td><td>可以直接取数计算的视图。</td></tr><tr><td><code>ExtensionCard</code></td><td>接口</td><td>扩展登记的卡片：kind 是带点的种类名。</td></tr><tr><td><code>ExtensionView</code></td><td>接口</td><td>扩展登记的主体视图：type 是带点的种类名。</td></tr><tr><td><code>GroupLevel</code></td><td>接口</td><td>分组报表的一级分组。</td></tr><tr><td><code>GroupView</code></td><td>接口</td><td>分组报表：多级分组，组内列出明细，组尾写小计，末尾写总计。</td></tr><tr><td><code>LinkTarget</code></td><td>接口</td><td>联动的一个目标：在目标卡片上按字段筛选。</td></tr><tr><td><code>MetricCard</code></td><td>接口</td><td>指标卡片。</td></tr><tr><td><code>ReportBody</code></td><td>类型</td><td>报表的主体。</td></tr><tr><td><code>TableCard</code></td><td>接口</td><td>表格卡片：内嵌一个明细表、分组报表或交叉表。</td></tr><tr><td><code>TableColumn</code></td><td>接口</td><td>表格的一列。</td></tr><tr><td><code>TableView</code></td><td>接口</td><td>明细表：逐行列出数据。</td></tr></tbody></table><h3 id="validate-checker" tabindex="-1">validate/checker <a class="header-anchor" href="#validate-checker" aria-label="Permalink to “validate/checker”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>REPORT_ISSUE_CODES</code></td><td>常量</td><td>报表自己的校验问题码，按字母序；通用问题码见 @xihan-ui/designer-kit/schema 的 CommonIssueCode。</td></tr><tr><td><code>ValidationIssue</code></td><td>类型</td><td>一条校验问题：path 只用对象键与数组下标，target 指出所在的带键对象。</td></tr><tr><td><code>ValidationIssueCode</code></td><td>类型</td><td>校验问题码：designer-kit/schema 的通用问题码、报表自己的（REPORT_ISSUE_CODES），以及扩展的问题码（扩展 id 的末段、一个点、码）。</td></tr></tbody></table><h3 id="validate-document" tabindex="-1">validate/document <a class="header-anchor" href="#validate-document" aria-label="Permalink to “validate/document”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>validateDocument</code></td><td>函数</td><td>校验报表文档，返回全部问题；没有问题时为空数组。</td></tr><tr><td><code>ValidateOptions</code></td><td>接口</td><td>校验选项。</td></tr></tbody></table>`,89)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};